import{_ as t,o as a,c as o,a0 as s}from"./chunks/framework.ChlVJx0I.js";const c=JSON.parse('{"title":"Output-starvation guard extension","description":"","frontmatter":{},"headers":[],"relativePath":"extensions/output-starvation.md","filePath":"extensions/output-starvation.md","lastUpdated":1790513785000}'),r={name:"extensions/output-starvation.md"};function n(i,e,u,d,h,l){return a(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="output-starvation-guard-extension" tabindex="-1">Output-starvation guard extension <a class="header-anchor" href="#output-starvation-guard-extension" aria-label="Permalink to &quot;Output-starvation guard extension&quot;">​</a></h1><p>Refuses a request whose output budget has collapsed to pi&#39;s floor.</p><p>pi&#39;s output clamp computes the Effective window minus the context estimate minus a safety margin, and floors the result at its own minimum. Any estimate over the window minus that margin saturates the clamp: the payload goes out carrying the floor as its max tokens, the provider answers a one-token non-answer, and the transcript records <code>stopReason: &quot;length&quot;</code>. That state is Output starvation, and a starved request is a failure, not a request.</p><h2 id="behavior" tabindex="-1">Behavior <a class="header-anchor" href="#behavior" aria-label="Permalink to &quot;Behavior&quot;">​</a></h2><ul><li>On every provider request, the guard reads the payload pi has already built. When the payload&#39;s budget is pi&#39;s saturated floor, it refuses: one report line and the run&#39;s abort. The provider is never contacted, the turn ends aborted instead of a one-token <code>length</code> answer, and pi never retries an abort.</li><li>The refusal is at most once per turn. The flag resets on every turn start, so a refusal can never become a retry storm.</li><li>A healthy budget - however small - goes out untouched, and the guard says nothing.</li><li>The report line names provider, model, the context estimate, the Effective window, and the budget pi computed: <ul><li><code>output starvation: refused (llama.cpp/m1): context estimate 13757, Effective window 16000, output budget 1</code></li></ul></li></ul><p>The estimate is a mirror of pi-ai&#39;s estimator - the function pi&#39;s clamp reads - run over the session projection, so the line names the figure that collapsed the budget. A failure to compute it degrades to 0 in the line; the trigger is the payload, never the estimate.</p><h2 id="how-it-works" tabindex="-1">How it works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How it works&quot;">​</a></h2><p>The decision lives in the engine-free core module (<code>extensions/output-starvation/guard.ts</code>): the trigger is the payload&#39;s budget compared to pi&#39;s floor (pinned to the value pi&#39;s clamp floors at, since the clamp&#39;s module is not importable from an extension), and the one place the report line exists. The pi wiring (<code>index.ts</code>) only binds the <code>before_provider_request</code>, <code>turn_start</code>, and <code>session_start</code> events and owns the refusal. The guard registers no compaction hook, so it cannot stand in the way of a compaction that would rescue the session, and it never touches the window, which stays Llama refresh&#39;s ownership. See <a href="/pi-extensions/adr/0028-output-starvation-guard-refuses-a-collapsed-output-budget.html">ADR 0028</a>.</p>',8)])])}const m=t(r,[["render",n]]);export{c as __pageData,m as default};
